const test=require('node:test'),assert=require('node:assert/strict'),{pathToFileURL}=require('node:url'),path=require('node:path');
test('fence runs remove stair steps while preserving an exact gate',async()=>{const {fenceRuns}=await import(pathToFileURL(path.join(__dirname,'../fence-runs.js')));const edges=[{points:[[0,0],[4,0]],gate:true}];let p=[4,0];for(let i=0;i<20;i++){const q=[p[0]+4,p[1]],r=[q[0],q[1]+4];edges.push({points:[p,q]},{points:[q,r]});p=r;}const out=fenceRuns(edges);assert.deepEqual(out.find(e=>e.gate),edges[0]);assert(out.length<edges.length/4);assert(out.every(e=>e.points.flat().every(Number.isFinite)));});
